/// facility: 320 by 320 metres.
pub static FACILITY: Map = Map::new(
    "facility",
    1.0,
    160.00,
    160.00,
    FACILITY_BRUSHES,
    FACILITY_SPAWNS,
    30,
);
// --- end of generated tables ---
/// Every map the build knows about.
pub static MAPS: &[&Map] = &[&ARENA, &YARD, &FACILITY];

pub fn by_name(name: &str) -> Option<&'static Map> {
    MAPS.iter().copied().find(|map| map.name == name)
}

/// The map the browser client is predicting against, as an index into `MAPS`.
///
/// The client's alone. The server's lobby never reads it: several matches run there at
/// once on different ground, and each holds its own map. A client is only ever
/// in one match, so it has one active map, set by `switch` from the map named
/// in `MatchStarted`.
static ACTIVE: AtomicUsize = AtomicUsize::new(UNSET);

/// No map chosen yet, so `active()` answers with the arena.
const UNSET: usize = usize::MAX;

fn index_of(name: &str) -> Option<usize> {
    MAPS.iter().position(|map| map.name == name)
}

/// Points the client's prediction at a map. Returns false, and changes
/// nothing, for a map this build does not have.
///
/// Called **between matches only**. A match is a fresh start with no world
/// state to carry across, so there is nothing for the new table to contradict;
/// switching mid-match would put the player's prediction on different ground
/// from the server's, and it is the caller's job not to.
pub fn switch(name: &str) -> bool {
    match index_of(name) {
        Some(index) => {
            ACTIVE.store(index, Ordering::Relaxed);
            true
        }
        None => false,
    }
}

pub fn active() -> &'static Map {
    match ACTIVE.load(Ordering::Relaxed) {
        UNSET => &ARENA,
        index => MAPS[index],
    }
}

/// The arena, under the name the tests have always used for it.
///
/// Tests pin a map on purpose rather than asking which one is active: what they
/// assert about stairs and spawns is true of this one specifically.
pub use ARENA as TEST_MAP;

#[cfg(test)]
mod tests {
    use super::*;
    use crate::sim::PLAYER_HALF_EXTENTS;
    use crate::sim::collide::overlaps_any;

    /// Every map in the build, because every one of them ships.
    ///
    /// These used to run on the arena alone, which was fine while it was the
    /// only map and became a hole the moment it was not: a second map is seven
    /// thousand generated brushes and a dozen generated spawns that nothing
    /// looked at. A spawn inside a wall is not a cosmetic fault in a game that
    /// pays per kill - it is a player who joins and falls out of the world.
    ///
    /// Failures name the map, since the tables are generated per map and only
    /// one of them is usually wrong.
    fn maps() -> impl Iterator<Item = &'static Map> {
        MAPS.iter().copied()
    }

    #[test]
    fn every_brush_is_well_formed() {
        for map in maps() {
            for (i, brush) in map.brushes.iter().enumerate() {
                assert!(
                    brush.min.x < brush.max.x
                        && brush.min.y < brush.max.y
                        && brush.min.z < brush.max.z,
                    "{}: brush {i} is inside out: {brush:?}",
                    map.name
                );
            }
        }
    }

    #[test]
    fn no_brush_is_absurd() {
        // Brushes used to be forbidden from overlapping, because the client
        // drew them and two surfaces at the same depth flicker. The client
        // draws the model now and these are invisible, so overlap is free -
        // the union of two boxes is exactly the shape a player collides with.
        // Props are emitted as their own bounding boxes and sit *on* the
        // structure they rest against, so most of them overlap something.
        //
        // What is still worth asserting is that nothing is a mistake: no brush
        // may swallow a meaningful slice of the map, which is what a mesh
        // wrongly classified as a prop would produce - the perimeter walls are
        // one mesh, and as a single box they would fill the map solid.
        let mut absurd = Vec::new();

        for map in maps() {
            let floor_area = (map.half_x * 2.0) * (map.half_z * 2.0);
            for (i, brush) in map.brushes.iter().enumerate().skip(PERIMETER_BRUSHES) {
                let size = brush.size();
                let footprint = size.x * size.z;
                if footprint > floor_area * 0.25 {
                    absurd.push(format!(
                        "{}: brush {i} covers {footprint:.0} m2 of a {floor_area:.0} m2 map: {:?}",
                        map.name,
                        brush.centre()
                    ));
                }
            }
        }

        assert!(absurd.is_empty(), "{}", absurd.join("\n  "));
    }

    #[test]
    fn there_are_enough_spawns_for_a_full_match() {
        // Against the map's own seat count. This used to compare with a
        // server-wide ten from before the lobby, which every map cleared
        // however many it actually seats - so a map seating thirty with
        // twelve spawns would have passed.
        for map in maps() {
            assert!(
                map.spawns.len() >= map.max_players,
                "{}: a full match of {} would have to reuse spawns",
                map.name,
                map.max_players
            );
        }
    }

    #[test]
    fn spawns_are_inside_the_map_and_not_inside_geometry() {
        // Collects every bad spawn rather than stopping at the first, so a map
        // edit is fixed in one pass instead of one failure at a time.
        let mut problems = Vec::new();

        for map in maps() {
            for (i, spawn) in map.spawns.iter().enumerate() {
                if spawn.position.x.abs() >= map.half_x || spawn.position.z.abs() >= map.half_z {
                    problems.push(format!(
                        "{}: spawn {i} at {:?} is outside the map",
                        map.name, spawn.position
                    ));
                }
                if overlaps_any(spawn.position, PLAYER_HALF_EXTENTS, map) {
                    let blocking: Vec<usize> = map
                        .brushes
                        .iter()
                        .enumerate()
                        .filter(|(_, b)| {
                            let min = spawn.position - PLAYER_HALF_EXTENTS;
                            let max = spawn.position + PLAYER_HALF_EXTENTS;
                            min.x < b.max.x
                                && max.x > b.min.x
                                && min.y < b.max.y
                                && max.y > b.min.y
                                && min.z < b.max.z
                                && max.z > b.min.z
                        })
                        .map(|(i, _)| i)
                        .collect();
                    problems.push(format!(
                        "{}: spawn {i} at {:?} is inside brush(es) {blocking:?}",
                        map.name, spawn.position
                    ));
                }
            }
        }

        assert!(
            problems.is_empty(),
            "bad spawns:\n  {}",
            problems.join("\n  ")
        );
    }

    #[test]
    fn spawns_face_open_ground() {
        // Spawning nose-first into a wall is disorienting and, in a game where
        // the first second can cost a dollar, unfair. Every spawn must have a
        // clear view ahead of it.
        const REQUIRED_CLEARANCE: f32 = 9.0;
        let mut problems = Vec::new();

        for map in maps() {
            for (i, spawn) in map.spawns.iter().enumerate() {
                let state = crate::sim::PlayerState::spawned_at(*spawn);
                let eye = state.eye_position();
                let ahead = crate::sim::look_direction(spawn.yaw, 0.0);

                let distance = crate::sim::hitscan::trace_world(eye, ahead, 200.0, map)
                    .unwrap_or(f32::INFINITY);
                if distance < REQUIRED_CLEARANCE {
                    problems.push(format!(
                        "{}: spawn {i} at {:?} faces a wall {distance:.1} m away",
                        map.name, spawn.position
                    ));
                }
            }
        }

        assert!(
            problems.is_empty(),
            "{} spawn(s) face into geometry:\n  {}",
            problems.len(),
            problems.join("\n  ")
        );
    }

    #[test]
    fn spawns_land_on_something_solid() {
        // A spawn over a hole would drop the player out of the world and kill
        // them the moment they joined.
        for map in maps() {
            for (i, spawn) in map.spawns.iter().enumerate() {
                let mut state = crate::sim::PlayerState::spawned_at(*spawn);
                for _ in 0..400 {
                    crate::sim::step_tick(&mut state, &idle(spawn.yaw), map);
                }
                assert!(
                    state.on_ground,
                    "{}: spawn {i} never landed; ended at {:?}",
                    map.name, state.position
                );
                assert!(
                    state.position.y > -5.0,
                    "{}: spawn {i} fell out of the world",
                    map.name
                );
            }
        }
    }

    #[test]
    fn a_spawn_does_not_slide_the_player_across_the_map() {
        // Landing is allowed to move a player down. It is not allowed to move
        // them sideways: there is no input, no velocity and nothing to slide
        // along, so any horizontal travel is the resolver pushing them out of
        // geometry they were placed inside.
        //
        // This is worth its own test rather than leaving it to
        // `spawns_land_on_something_solid`, which only asks whether they
        // eventually stopped falling. One yard spawn passed that while
        // sliding eleven metres first, ending up against the perimeter wall
        // looking out of the map - which is what the player reported as
        // starting at the back of the map, and it was not the spawn table's
        // doing at all.
        const DRIFT_LIMIT: f32 = 1.0;
        let mut problems = Vec::new();

        for map in maps() {
            for (i, spawn) in map.spawns.iter().enumerate() {
                let mut state = crate::sim::PlayerState::spawned_at(*spawn);
                for _ in 0..400 {
                    crate::sim::step_tick(&mut state, &idle(spawn.yaw), map);
                }
                let moved = Vec3::new(
                    state.position.x - spawn.position.x,
                    0.0,
                    state.position.z - spawn.position.z,
                )
                .length();
                if moved > DRIFT_LIMIT {
                    problems.push(format!(
                        "{}: spawn {i} at {:?} slid {moved:.1} m to {:?} without being touched",
                        map.name, spawn.position, state.position
                    ));
                }
            }
        }

        assert!(problems.is_empty(), "{}", problems.join("\n  "));
    }

    #[test]
    fn every_map_is_closed() {
        // The brushes are generated now, so the thing most worth asserting is
        // no longer that any one of them is right - it is that together they
        // still hold a player in. This runs the real simulation rather than
        // inspecting the table: from every spawn, sprint in eight directions
        // for ten seconds and end up still inside the map, and still above the
        // floor.
        //
        // A gap in the perimeter or a hole in the floor is not a graphical
        // fault in a game that pays per kill - it is a player who cannot be
        // shot, banking a life nobody can end.
        const SECONDS: usize = 10;
        let ticks = SECONDS * crate::net::TICK_HZ as usize;
        let mut escapes = Vec::new();

        for map in maps() {
            for (i, spawn) in map.spawns.iter().enumerate() {
                for step in 0..8 {
                    let yaw = step as f32 * std::f32::consts::FRAC_PI_4;
                    let mut state = crate::sim::PlayerState::spawned_at(*spawn);
                    let mut command = idle(yaw);
                    command.forward = 1.0;
                    // Hold jump too, so this also covers climbing onto
                    // something and trying to hop the wall from the top of it.
                    command.buttons = crate::sim::Buttons::empty();
                    command.buttons.set(crate::sim::Buttons::JUMP, true);

                    for _ in 0..ticks {
                        crate::sim::step_tick(&mut state, &command, map);

                        if state.position.y < -1.0 {
                            escapes.push(format!(
                                "{}: spawn {i} running at yaw {yaw:.2} fell through the floor to {:?}",
                                map.name, state.position
                            ));
                            break;
                        }
                        if state.position.x.abs() > map.half_x + 1.0
                            || state.position.z.abs() > map.half_z + 1.0
                        {
                            escapes.push(format!(
                                "{}: spawn {i} running at yaw {yaw:.2} left the map at {:?}",
                                map.name, state.position
                            ));
                            break;
                        }
                    }
                }
            }
        }

        assert!(
            escapes.is_empty(),
            "{} escape(s):\n  {}",
            escapes.len(),
            escapes.join("\n  ")
        );
    }

    // The two below are about the arena specifically. The coordinates are its
    // art's, and what they assert - that these particular flights are walkable
    // and do not shove - is a claim about those flights, not about maps in
    // general.

    /// (x, z at the foot, yaw climbing up) for the arena's two staircases.
    const FLIGHTS: [(f32, f32, f32); 2] = [
        (17.48, -14.60, std::f32::consts::PI), // rises towards +Z
        (17.48, 14.60, 0.0),                   // rises towards -Z
    ];

    #[test]
    fn the_stairs_can_be_walked_up() {
        // The arena has two staircases, and for a while it had neither: the
        // brush generator only noticed geometry that was in the way of a
        // standing body, so the treads above chest height read as open floor
        // and both staircases stopped half way up with a two metre drop off
        // the end. A map with a raised half nobody can reach is a much smaller
        // map than it looks.
        //
        // These are the two flights, climbed from the bottom. The coordinates
        // are the art's, so a change to the model moves them - which is the
        // point: this fails loudly rather than quietly removing the upstairs.
        //
        // Jump is held throughout because one flight has to be hopped rather
        // than walked: its bottom tread is 0.75 m, over the 0.55 m a walking
        // player steps up and under the 1.13 m a jump clears. That is the art,
        // not the collision - the other flight is 0.25 m treads all the way and
        // walks up cleanly.
        const SECONDS: usize = 6;

        for (index, (x, z, yaw)) in FLIGHTS.iter().enumerate() {
            let spawn = Spawn {
                position: Vec3::new(*x, 1.2, *z),
                yaw: *yaw,
            };
            let mut state = crate::sim::PlayerState::spawned_at(spawn);
            let mut command = idle(*yaw);
            command.forward = 1.0;
            command.buttons.set(crate::sim::Buttons::JUMP, true);

            let mut highest = state.position.y;
            for _ in 0..(SECONDS * crate::net::TICK_HZ as usize) {
                crate::sim::step_tick(&mut state, &command, &ARENA);
                highest = highest.max(state.position.y);
            }

            assert!(
                highest > 4.60,
                "staircase {index} from {:?} only reached {highest:.2} m; \
                 a player climbing it should clear 4.6 m",
                spawn.position
            );
        }
    }

    #[test]
    fn the_north_west_roof_can_be_walked_onto() {
        // The two storey building in the north-west corner had a roof with
        // no way onto it. 56 m2 of standing room, visible from most of the
        // map, and every route to it short by more than a jump: 2.10 m up
        // from the stair that passes its west side, 2.35 m up from its own
        // first floor. A player could get to the floor below and no further,
        // which is what it looked like from inside the game - a corner that
        // simply refused.
        //
        // `scripts/extend-arena.py` builds a ramp up the building's south
        // face, in the open yard, to a landing beside the roof. This walks
        // it, from the bottom, on foot.
        //
        // No jump is held, deliberately. A way up that has to be hopped is a
        // way up that is still broken, just less obviously, and this one
        // exists precisely because the corner was unreachable.
        const FOOT: Vec3 = Vec3::new(-2.20, 1.2, 25.78);
        const CLIMBING_WEST: f32 = std::f32::consts::FRAC_PI_2;
        const ROOF: f32 = 4.85;
        const SECONDS: usize = 8;

        let mut state = crate::sim::PlayerState::spawned_at(Spawn {
            position: FOOT,
            yaw: CLIMBING_WEST,
        });
        let mut command = idle(CLIMBING_WEST);
        command.forward = 1.0;

        let mut highest = state.position.y;
        for _ in 0..(SECONDS * crate::net::TICK_HZ as usize) {
            crate::sim::step_tick(&mut state, &command, &ARENA);
            highest = highest.max(state.position.y);
        }

        // The position is the centre of the collision box, so the feet are
        // half its height below it. Half a metre of slack under the roof
        // proper, to allow for the landing coming back a quantisation step
        // low, and no more: the floor below is 2.35 m down and must not pass.
        let feet = highest - PLAYER_HALF_EXTENTS.y;
        assert!(
            feet > ROOF - 0.5,
            "walking up the north-west ramp reached {feet:.2} m; the roof it \
             climbs to is at {ROOF:.2} m and the floor below it at 2.50 m"
        );
    }

    /// Every ramp `scripts/extend-arena.py` builds: where its foot is, which
    /// way is up it, the height it climbs to and the run it takes to. The
    /// north-west one first, then the two districts' in the order the script
    /// lists their blocks.
    const ARENA_RAMPS: [(f32, f32, f32, f32, f32); 13] = {
        const UP_Z: f32 = std::f32::consts::PI; // rising towards +z
        const DOWN_Z: f32 = 0.0; // rising towards -z
        const WEST: f32 = std::f32::consts::FRAC_PI_2;
        [
            (-3.00, 25.78, WEST, 4.83, 8.5),
            (31.25, -15.80, DOWN_Z, 3.58, 6.2),
            (45.25, -9.70, DOWN_Z, 5.98, 10.3),
            (30.25, 8.30, DOWN_Z, 5.98, 10.3),
            (37.75, -12.20, UP_Z, 3.58, 6.2),
            (24.75, 5.80, UP_Z, 3.58, 6.2),
            (45.25, 9.00, UP_Z, 5.98, 9.0),
            (-31.25, -12.50, DOWN_Z, 5.98, 7.5),
            (-45.25, -17.80, DOWN_Z, 3.58, 6.2),
            (-30.25, 6.20, DOWN_Z, 3.58, 6.2),
            (-44.25, -14.30, UP_Z, 5.98, 10.3),
            (-24.75, 3.70, UP_Z, 5.98, 10.3),
            (-38.75, 13.80, UP_Z, 3.58, 6.2),
        ]
    };

    #[test]
    fn every_ramp_in_the_arena_takes_a_player_to_the_top() {
        // The arena's ways up were flights of stairs, and Conrad could not
        // climb them. Straight up the middle they worked - which is all the
        // tests then asked - but walked up a few degrees off their line, as
        // anybody does, they put the player off their open side: from the
        // foot, eleven degrees off line or 0.8 m off centre failed on most
        // of them.
        //
        // They are ramps now, three metres wide, with a wall a metre high
        // down each side. This walks every one from just short of its foot,
        // straight, eleven degrees either way, and 0.8 m either side of the
        // middle, on foot, and asks that each gets to within half a metre of
        // the top.
        const SECONDS: usize = 6;
        const SKEW: f32 = 0.2;
        let mut failed = Vec::new();

        for (index, (x, z, yaw, top, _run)) in ARENA_RAMPS.iter().enumerate() {
            let ahead = crate::sim::look_direction(*yaw, 0.0);
            let across = Vec3::new(-ahead.z, 0.0, ahead.x);
            for skew in [0.0, -SKEW, SKEW] {
                for offset in [0.0, -0.8, 0.8] {
                    let start = Vec3::new(*x, 1.0, *z) - ahead * 0.8 + across * offset;
                    let mut state = crate::sim::PlayerState::spawned_at(Spawn {
                        position: start,
                        yaw: yaw + skew,
                    });
                    let mut command = idle(yaw + skew);
                    command.forward = 1.0;
                    let mut highest = state.position.y;
                    for _ in 0..(SECONDS * crate::net::TICK_HZ as usize) {
                        crate::sim::step_tick(&mut state, &command, &ARENA);
                        highest = highest.max(state.position.y);
                    }
                    let feet = highest - PLAYER_HALF_EXTENTS.y;
                    if feet < top - 0.5 {
                        failed.push(format!(
                            "ramp {index} from {start:?}, {skew:+.1} rad off line: \
                             reached {feet:.2} m of {top:.2}"
                        ));
                    }
                }
            }
        }
        assert!(failed.is_empty(), "{}", failed.join("\n"));
    }

    #[test]
    fn running_down_a_ramp_keeps_the_player_on_it() {
        // The collision holds a slope as quarter-metre steps, and walking
        // off a step used to be a fall: running down a thirty-degree ramp at
        // full speed left the ground for 0.4 s and three metres at a time,
        // landing at 9 m/s with the thump and the dip of a fall each time.
        // A walking player is now put down on anything within a step below
        // (`collide::MAX_STEP_DOWN`), so the whole way down is on the ground.
        let mut failed = Vec::new();
        for (index, (x, z, yaw, top, run)) in ARENA_RAMPS.iter().enumerate() {
            let ahead = crate::sim::look_direction(*yaw, 0.0);
            let foot = Vec3::new(*x, 0.0, *z);
            let down = *yaw + std::f32::consts::PI;
            let mut state = crate::sim::PlayerState::spawned_at(Spawn {
                position: foot + ahead * (run - 0.8) + Vec3::Y * (top + 1.2),
                yaw: down,
            });
            let mut command = idle(down);
            for _ in 0..32 {
                crate::sim::step_tick(&mut state, &command, &ARENA);
            }
            command.forward = 1.0;
            let mut airborne = 0;
            for _ in 0..(2 * crate::net::TICK_HZ as usize) {
                crate::sim::step_tick(&mut state, &command, &ARENA);
                let along = (state.position - foot).dot(ahead);
                if along < 0.3 {
                    break;
                }
                if !state.on_ground {
                    airborne += 1;
                }
            }
            if airborne > 0 {
                failed.push(format!(
                    "ramp {index}: off the ground for {airborne} ticks running down it"
                ));
            }
        }
        assert!(failed.is_empty(), "{}", failed.join("\n"));
    }

    #[test]
    fn walking_off_a_roof_is_still_a_fall_and_a_jump_is_still_a_jump() {
        // Putting a walking player down onto what is below is for steps. A
        // drop taller than one is a fall, as it always was, and a jump off a
        // ramp leaves it - neither may be pulled back to the ground.
        //
        // The first block of the east district: roof at 3.6 m over x 23..33,
        // z -32..-22. Walk west off it.
        let mut state = crate::sim::PlayerState::spawned_at(Spawn {
            position: Vec3::new(24.5, 3.6 + 1.2, -27.0),
            yaw: std::f32::consts::FRAC_PI_2,
        });
        let mut command = idle(std::f32::consts::FRAC_PI_2);
        for _ in 0..32 {
            crate::sim::step_tick(&mut state, &command, &ARENA);
        }
        assert!(
            state.on_ground,
            "test setup: should be standing on the roof"
        );
        command.forward = 1.0;
        let mut fell = false;
        for _ in 0..64 {
            crate::sim::step_tick(&mut state, &command, &ARENA);
            if !state.on_ground && state.position.x < 23.0 {
                fell = true;
                break;
            }
        }
        assert!(fell, "walking off a 3.6 m roof should be a fall");

        // Half way up the north-west ramp, jump: the next tick is in the air.
        let (x, z, yaw, _top, _run) = ARENA_RAMPS[0];
        let ahead = crate::sim::look_direction(yaw, 0.0);
        let mut state = crate::sim::PlayerState::spawned_at(Spawn {
            position: Vec3::new(x, 0.0, z) + ahead * 4.0 + Vec3::Y * 4.0,
            yaw,
        });
        let mut command = idle(yaw);
        for _ in 0..32 {
            crate::sim::step_tick(&mut state, &command, &ARENA);
        }
        assert!(
            state.on_ground,
            "test setup: should be standing on the ramp"
        );
        command.forward = 1.0;
        command.buttons.set(crate::sim::Buttons::JUMP, true);
        crate::sim::step_tick(&mut state, &command, &ARENA);
        assert!(
            !state.on_ground,
            "a jump from a ramp was pulled back down onto it"
        );
    }

    #[test]
    fn a_ramp_wall_cannot_be_stepped_onto() {
        // A ramp's walls are drawn sloped and collide as a box a cell long
        // each, their tops on the drawn wall. Left to the generator with the
        // rest of the structure they were smoothed: it votes each wall cell
        // to the height most common round it, every height along a sloped
        // wall is different, so each went to the lowest in reach - and near
        // the top the wall stood half a metre over the slope, a step onto it
        // and off the outside.
        //
        // So: start on the slope past where its walls reach full height,
        // walk up it strafing hard into one wall, and never be standing
        // anywhere but on the slope's own width. The slope is 1.5 m either
        // side of its middle and the player 0.35 m either side of theirs.
        const SECONDS: usize = 3;
        const ON_THE_SLOPE: f32 = 1.5 - 0.35 + 0.1;
        let mut failed = Vec::new();
        for (index, (x, z, yaw, _top, run)) in ARENA_RAMPS.iter().enumerate() {
            let ahead = crate::sim::look_direction(*yaw, 0.0);
            let side = Vec3::new(-ahead.z, 0.0, ahead.x);
            let foot = Vec3::new(*x, 0.0, *z);
            for strafe in [-1.0_f32, 1.0] {
                let start = foot + ahead * 2.5 + Vec3::Y * (2.5 * 0.85 + 1.2);
                let mut state = crate::sim::PlayerState::spawned_at(Spawn {
                    position: start,
                    yaw: *yaw,
                });
                let mut command = idle(*yaw);
                command.forward = 1.0;
                command.right = strafe;
                for _ in 0..(SECONDS * crate::net::TICK_HZ as usize) {
                    crate::sim::step_tick(&mut state, &command, &ARENA);
                    let along = (state.position - foot).dot(ahead);
                    let across = (state.position - foot).dot(side);
                    if along > run - 0.5 {
                        break;
                    }
                    if state.on_ground && across.abs() > ON_THE_SLOPE {
                        failed.push(format!(
                            "ramp {index}: strafing {strafe:+.0} stood the player {across:.2} m \
                             off its middle, {along:.2} m along it, at {:.2} m",
                            state.position.y - PLAYER_HALF_EXTENTS.y
                        ));
                        break;
                    }
                }
            }
        }
        assert!(failed.is_empty(), "{}", failed.join("\n"));
    }

    #[test]
    fn climbing_a_staircase_does_not_shove_the_player_sideways() {
        // Walking up a flight while pointing slightly off its axis must still
        // go up the flight.
        //
        // It did not, and the cause is worth remembering. The collision table
        // used to be a field of quarter-metre boxes at slightly different
        // heights - a washboard. Crossing it diagonally, the resolver caught on
        // every seam, and each catch resolved as a slide along one axis. The
        // slides all went the same way, so holding forward on a staircase
        // walked a visible curve off the side of it.
        //
        // Axis-aligned headings hide this completely, because one component of
        // the movement is zero and there is no seam to catch. So these are all
        // deliberately off-axis.
        const SECONDS: usize = 5;
        const TOP_OF_FLIGHT: f32 = 4.37;
        let ticks = SECONDS * crate::net::TICK_HZ as usize;
        let mut problems = Vec::new();

        for (index, (x, z, straight)) in FLIGHTS.iter().enumerate() {
            // A tenth of a radian is about six degrees - the heading error of
            // someone walking up a flight without aiming carefully. A quarter
            // would walk them off the side of a two-metre staircase in eight
            // metres of run, which is not a bug but arithmetic.
            for skew in [-0.10_f32, 0.10] {
                let yaw = straight + skew;
                let spawn = Spawn {
                    position: Vec3::new(*x, 1.2, *z),
                    yaw,
                };
                let mut state = crate::sim::PlayerState::spawned_at(spawn);
                // Walking, not jumping. A player bouncing up a staircase is
                // airborne half the time and lands where the arc puts them,
                // which is chaotic for reasons that have nothing to do with the
                // collision resolver. This is about whether the ground pushes
                // them sideways.
                let mut command = idle(yaw);
                command.forward = 1.0;

                let start = state.position;
                let ahead = crate::sim::look_direction(*straight, 0.0);
                let sideways = Vec3::new(-ahead.z, 0.0, ahead.x);

                // Measured at the top of the flight, not after a fixed time.
                // Past the top the player is walking across open roof and
                // drifting honestly with their heading, which says nothing
                // about the stairs.
                let mut reached = 0.0_f32;
                let mut across_at_top = None;
                for _ in 0..ticks {
                    crate::sim::step_tick(&mut state, &command, &ARENA);
                    reached = reached.max(state.position.y);
                    if across_at_top.is_none() && state.position.y >= TOP_OF_FLIGHT {
                        across_at_top = Some((state.position - start).dot(sideways).abs());
                    }
                }

                match across_at_top {
                    None => problems.push(format!(
                        "flight {index} skewed {skew:+.2}: never got up it, \
                         reaching only {reached:.2} m"
                    )),
                    // The flight is about 8 m of run. Six degrees of heading
                    // error across that is 0.85 m of honest sideways travel;
                    // anything past 1.6 m is the ground shoving.
                    Some(across) if across > 1.6 => problems.push(format!(
                        "flight {index} skewed {skew:+.2}: reached the top but \
                         {across:.2} m off to one side"
                    )),
                    Some(_) => {}
                }
            }
        }

        assert!(problems.is_empty(), "{}", problems.join("\n  "));
    }

    #[test]
    fn switching_to_a_map_this_build_lacks_changes_nothing() {
        // The client reports a false here as "this build has no such map" and
        // stays where it was; a half-applied switch would leave it predicting
        // against a table nobody chose. Only the refusal is tested, so the
        // shared `ACTIVE` is left as the other tests found it.
        let before = active().name;
        assert!(!switch("no such map"), "an unknown map must be refused");
        assert_eq!(active().name, before);
    }

    #[test]
    fn survey_report() {
        for map in MAPS.iter().copied() {
            let mut inside = 0usize;
            let mut worst_depth = 0.0f32;
            let mut climbs = 0usize;
            let mut drift_total = 0.0f32;
            let mut worst_drift = 0.0f32;
            let mut stuck = 0usize;
            let mut runs = 0usize;

            for spawn in map.spawns.iter() {
                for step in 0..16 {
                    let yaw = step as f32 * std::f32::consts::TAU / 16.0;
                    let mut state = crate::sim::PlayerState::spawned_at(*spawn);
                    for _ in 0..60 {
                        crate::sim::step_tick(&mut state, &idle(yaw), map);
                    }
                    let start = state.position;
                    let ahead = crate::sim::look_direction(yaw, 0.0);
                    let side = Vec3::new(-ahead.z, 0.0, ahead.x);

                    let mut command = idle(yaw);
                    command.forward = 1.0;
                    let mut gained = 0.0f32;
                    let mut moved = 0.0f32;
                    let base = state.position.y;

                    for tick in 0..400 {
                        if tick % 40 == 0 {
                            command.buttons.set(crate::sim::Buttons::JUMP, true);
                        } else {
                            command.buttons.set(crate::sim::Buttons::JUMP, false);
                        }
                        crate::sim::step_tick(&mut state, &command, map);

                        if crate::sim::collide::overlaps_any(
                            state.position,
                            PLAYER_HALF_EXTENTS,
                            map,
                        ) {
                            inside += 1;
                            let mut depth = 0.0f32;
                            let lo = state.position - PLAYER_HALF_EXTENTS;
                            let hi = state.position + PLAYER_HALF_EXTENTS;
                            map.near(lo, hi, |_, b| {
                                let overlap = (hi.min(b.max) - lo.max(b.min)).min_element();
                                if overlap > depth {
                                    depth = overlap;
                                }
                                true
                            });
                            if depth > worst_depth {
                                worst_depth = depth;
                            }
                        }
                        gained = gained.max(state.position.y - base);
                        moved = moved.max((state.position - start).dot(ahead));
                    }

                    runs += 1;
                    if moved < 1.0 {
                        stuck += 1;
                    }
                    if gained > 1.0 {
                        climbs += 1;
                        let across = (state.position - start).dot(side).abs();
                        drift_total += across;
                        if across > worst_drift {
                            worst_drift = across;
                        }
                    }
                }
            }

            println!(
                "{}: {runs} runs, {stuck} went nowhere, {inside} ticks inside geometry \
                 (worst {worst_depth:.3} m), {climbs} climbed, \
                 mean sideways {:.2} m, worst {worst_drift:.2} m",
                map.name,
                if climbs > 0 {
                    drift_total / climbs as f32
                } else {
                    0.0
                },
            );
        }
    }

    /// Can a player actually walk from one place to the other?
    ///
    /// Asked of `move_and_slide` rather than of a mask over the brush table.
    /// Every mask is a model of walking, and the two written for the
    /// generator were wrong in opposite directions - one joined yards that
    /// touch at a single cell, the other cut an upstairs off from its own
    /// stairs. This uses the thing being modelled.
    ///
    /// A breadth-first search over half-metre cells. Moving between two of
    /// them is attempted with the real resolver, including the step up and
    /// the settle back down, and counts only if the player arrives in the
    /// next cell still on the ground. Returns every cell reachable from the
    /// start, with the height they arrive at.
    fn walk_from(map: &'static Map, start: Vec3) -> std::collections::HashMap<(i32, i32), f32> {
        use std::collections::{HashMap, VecDeque};

        const CELL: f32 = 0.5;
        // Enough to cross the larger map many times over; a cap only so that
        // a bug here cannot hang the suite.
        const MAX_CELLS: usize = 400_000;

        let key = |p: Vec3| ((p.x / CELL).round() as i32, (p.z / CELL).round() as i32);

        let mut seen: HashMap<(i32, i32), f32> = HashMap::new();
        let mut queue = VecDeque::new();
        seen.insert(key(start), start.y);
        queue.push_back((key(start), start));

        while let Some((_, from)) = queue.pop_front() {
            if seen.len() > MAX_CELLS {
                break;
            }
            for (dx, dz) in [(CELL, 0.0), (-CELL, 0.0), (0.0, CELL), (0.0, -CELL)] {
                // A little downward with the step, so the move settles onto
                // whatever it climbed and a walk off a kerb resolves as a
                // step down rather than as hanging in the air.
                let moved = crate::sim::collide::move_and_slide(
                    from,
                    PLAYER_HALF_EXTENTS,
                    Vec3::new(dx, -CELL, dz),
                    map,
                );
                if !moved.on_ground {
                    continue;
                }
                let arrived = key(moved.position);
                // It has to have actually got somewhere, not slid along the
                // wall it was pushed into.
                if arrived == key(from) || seen.contains_key(&arrived) {
                    continue;
                }
                seen.insert(arrived, moved.position.y);
                queue.push_back((arrived, moved.position));
            }
        }
        seen
    }

    #[test]
    fn the_rooms_can_be_walked_into() {
        // The arena has two buildings with open interiors, and for a while a
        // player could not get into either: the height field held one number
        // per column and used it both for "how high is the obstacle here" and
        // "how high is the surface a player stands on here". Those are the
        // same for a crate and opposite for a roof. `climb` walked a player
        // up the stairs onto the roof, recorded 3.75 m for every column under
        // it, and the ground pass then filled each of those columns solid
        // from the floor. Two whole rooms, 21% of the map, sealed.
        //
        // These are points inside them. The coordinates are the art's, so a
        // change to the model moves them, which is the point: this fails
        // loudly rather than quietly bricking up the building again.
        const INSIDE: [(f32, f32); 2] = [(2.88, -1.72), (-1.15, 32.08)];
        const CELL: f32 = 0.5;

        let mut state = crate::sim::PlayerState::spawned_at(ARENA.spawn(0));
        for _ in 0..200 {
            crate::sim::step_tick(&mut state, &idle(0.0), &ARENA);
        }
        let reached = walk_from(&ARENA, state.position);

        for (x, z) in INSIDE {
            let key = ((x / CELL).round() as i32, (z / CELL).round() as i32);
            let near = (-2..=2)
                .any(|dx| (-2..=2).any(|dz| reached.contains_key(&(key.0 + dx, key.1 + dz))));
            assert!(
                near,
                "the room at ({x}, {z}) cannot be walked into from a spawn"
            );
        }
    }

    #[test]
    fn every_spawn_can_reach_every_other() {
        // A map's walkable floor is not one piece. The yard breaks into
        // hundreds of pieces: the main yard, and then fenced side strips,
        // roofed bays and pockets behind stacks. A spawn in one of those is
        // not a poor spawn, it is a player who cannot join the game - they
        // spend the match alone behind a fence watching it happen.
        //
        // Five of the yard's twelve were in one when this was written.
        const CELL: f32 = 0.5;
        let mut problems = Vec::new();

        for map in maps() {
            // Settle the first spawn, then walk everywhere from it.
            let mut state = crate::sim::PlayerState::spawned_at(map.spawn(0));
            for _ in 0..200 {
                crate::sim::step_tick(&mut state, &idle(0.0), map);
            }
            let reached = walk_from(map, state.position);

            for (i, spawn) in map.spawns.iter().enumerate().skip(1) {
                let mut other = crate::sim::PlayerState::spawned_at(*spawn);
                for _ in 0..200 {
                    crate::sim::step_tick(&mut other, &idle(spawn.yaw), map);
                }
                let here = (
                    (other.position.x / CELL).round() as i32,
                    (other.position.z / CELL).round() as i32,
                );
                // Within a cell either way, because the settle can land a
                // hair over a boundary from where the walk arrived.
                let joined = (-1..=1).any(|dx| {
                    (-1..=1).any(|dz| {
                        reached
                            .get(&(here.0 + dx, here.1 + dz))
                            .is_some_and(|y| (y - other.position.y).abs() < 1.5)
                    })
                });
                if !joined {
                    problems.push(format!(
                        "{}: spawn {i} at {:?} cannot be walked to from spawn 0",
                        map.name, spawn.position
                    ));
                }
            }
        }

        assert!(
            problems.is_empty(),
            "{} spawn(s) are cut off from the game:\n  {}",
            problems.len(),
            problems.join("\n  ")
        );
    }

    fn idle(yaw: f32) -> crate::sim::InputCommand {
        crate::sim::InputCommand {
            seq: 0,
            forward: 0.0,
            right: 0.0,
            yaw,
            pitch: 0.0,
            buttons: crate::sim::Buttons::empty(),
        }
    }

    // The two below are about the facility specifically, the way the two
    // above are about the arena: the coordinates are `build-facility.py`'s,
    // so moving a stair there means moving it here, and a stair that stops
    // working fails here rather than in somebody's match.

    /// (what, x, z at the foot, yaw that climbs it, height it reaches) for the
    /// facility's ways up. Every one of these broke at least once while the
    /// map was being built: a rail across the landing, a flight half a metre
    /// short of its deck, treads extended to the roof above them.
    const FACILITY_CLIMBS: [(&str, f32, f32, f32, f32); 15] = [
        ("compound watchtower, north-west", -53.3, -40.8, 0.0, 6.0),
        (
            "compound watchtower, south-west",
            -53.3,
            36.8,
            std::f32::consts::PI,
            6.0,
        ),
        ("pipe rack, west end", -43.25, 4.0, 0.0, 5.0),
        ("pipe rack, east end", 43.25, 4.0, 0.0, 5.0),
        ("factory roof", 6.5, 28.0, std::f32::consts::FRAC_PI_2, 8.0),
        (
            "factory gallery",
            -42.0,
            35.4,
            -std::f32::consts::FRAC_PI_2,
            3.75,
        ),
        (
            "office upper floor",
            31.0,
            26.2,
            std::f32::consts::FRAC_PI_2,
            3.25,
        ),
        ("office roof", 24.0, 43.5, 0.0, 7.0),
        ("the tanks", 7.0, -34.0, -std::f32::consts::FRAC_PI_2, 7.5),
        (
            "the silo gantry",
            -55.0,
            -20.4,
            -std::f32::consts::FRAC_PI_2,
            9.0,
        ),
        (
            "north-east hangar gallery",
            86.5,
            -109.4,
            -std::f32::consts::FRAC_PI_2,
            3.75,
        ),
        (
            "east warehouse gallery",
            108.0,
            7.4,
            -std::f32::consts::FRAC_PI_2,
            3.75,
        ),
        ("the dam", -109.7, 92.0, std::f32::consts::PI, 4.5),
        ("the footbridge", 109.5, 90.0, std::f32::consts::PI, 5.0),
        ("the summit", -101.75, -132.0, 0.0, 7.5),
    ];

    #[test]
    fn the_facility_high_ground_can_be_climbed() {
        let mut failures = Vec::new();
        for (what, x, z, yaw, height) in FACILITY_CLIMBS {
            let spawn = Spawn {
                position: Vec3::new(x, 1.2, z),
                yaw,
            };
            let mut state = crate::sim::PlayerState::spawned_at(spawn);
            for _ in 0..60 {
                crate::sim::step_tick(&mut state, &idle(yaw), &FACILITY);
            }
            let mut command = idle(yaw);
            command.forward = 1.0;
            let mut highest = state.position.y;
            for _ in 0..(64 * 5) {
                crate::sim::step_tick(&mut state, &command, &FACILITY);
                highest = highest.max(state.position.y);
            }
            let feet = highest - PLAYER_HALF_EXTENTS.y;
            if feet < height - 0.3 {
                failures.push(format!("{what}: got to {feet:.2} m of {height:.2}"));
            }
        }
        assert!(failures.is_empty(), "{}", failures.join("\n  "));
    }

    #[test]
    fn the_facility_river_cannot_be_entered() {
        // The river is drawn below the floor and the floor over it is still
        // there - invisible - so a player who got into the cut would be
        // standing on the water. The flood walls are what keep them out,
        // and the road bridge is the only place a walk crosses at water
        // level. A gap in a wall shows up here as floor reached inside it.
        const CELL: f32 = 0.5;
        let mut state = crate::sim::PlayerState::spawned_at(FACILITY.spawn(0));
        for _ in 0..200 {
            crate::sim::step_tick(&mut state, &idle(0.0), &FACILITY);
        }
        let reached = walk_from(&FACILITY, state.position);
        let wet: Vec<(f32, f32)> = reached
            .iter()
            .map(|((x, z), y)| {
                (
                    *x as f32 * CELL,
                    *z as f32 * CELL,
                    *y - PLAYER_HALF_EXTENTS.y,
                )
            })
            .filter(|(x, z, feet)| {
                *z > 106.3 && *z < 129.7 && *feet < 1.0 && !(8.0..=24.0).contains(x)
            })
            .map(|(x, z, _)| (x, z))
            .collect();
        assert!(
            wet.is_empty(),
            "{} cells of the river can be walked onto, e.g. {:?}",
            wet.len(),
            &wet[..wet.len().min(5)]
        );
    }

    #[test]
    fn the_final_circle_is_ground_everybody_can_walk_to() {
        // The circle burns anybody outside it and closes on the map's
        // middle. If that middle were a sealed room, or a roof with no
        // stairs, the last minute of every match would kill everybody in it
        // - and a match where nobody is left alive is stakes settled as
        // abandons, not a winner. So there must be floor inside the final
        // circle, reachable on foot from the spawns, and room on it for a
        // fight rather than a queue.
        const CELL: f32 = 0.5;
        const ENOUGH_SQUARE_METRES: f32 = 60.0;
        let inside = crate::sim::ZONE_FINAL_RADIUS - 1.0;
        for map in maps() {
            let mut state = crate::sim::PlayerState::spawned_at(map.spawn(0));
            for _ in 0..200 {
                crate::sim::step_tick(&mut state, &idle(0.0), map);
            }
            let reached = walk_from(map, state.position);
            let cells = reached
                .keys()
                .filter(|(x, z)| (*x as f32 * CELL).hypot(*z as f32 * CELL) <= inside)
                .count();
            let area = cells as f32 * CELL * CELL;
            assert!(
                area >= ENOUGH_SQUARE_METRES,
                "{}: only {area} m2 inside the final circle can be walked to",
                map.name
            );
        }
    }
}
